<script setup lang="ts">
import { ref } from 'vue'
const login = ref(''), password = ref(''), error = ref(''), loading = ref(false)
async function submit(): Promise<void> { loading.value = true; error.value = ''; try { const response = await fetch(`${import.meta.env.VITE_API_BASE_URL ?? 'http://127.0.0.1:8010/api/v1'}/auth/login`, { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify({ login: login.value, password: password.value }) }); const payload = await response.json(); if (!response.ok || !payload.success) throw new Error(payload.message ?? 'Login gagal.'); if (!['admin', 'staff'].includes(payload.data.user.role)) throw new Error('Akun ini tidak memiliki akses dashboard.'); sessionStorage.setItem('tb_token', payload.data.token); sessionStorage.setItem('tb_user', JSON.stringify(payload.data.user)); window.location.reload() } catch (exception) { error.value = exception instanceof Error ? exception.message : 'Tidak dapat terhubung ke server.' } finally { loading.value = false } }
</script>
<template><main class="login-page"><form @submit.prevent="submit"><div class="brand">TB<span>Care</span></div><h1>Masuk Petugas</h1><p>Gunakan akun Admin atau Staff Puskesmas.</p><label>Username atau Email<input v-model="login" autocomplete="username" required></label><label>Password<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="error" class="login-error">{{ error }}</p><button :disabled="loading">{{ loading ? 'Memeriksa…' : 'Masuk ke Dashboard' }}</button><a href="/">Kembali ke aplikasi pasien</a></form></main></template>
